-- =============================================================================
-- 02b_snowpipe.sql | Snowpipe: a file that lands in the ADLS container is loaded into Bronze within about a minute
-- One pipe per batch feed (20), same file format as the COPY in 02_bronze_load.sql. Run after 01c_adls_stages.sql and
-- after the initial load (02), and only after azure/03_upload.sh has cleared the event queue: pipes load files that
-- arrive from now on, so the files the initial COPY already loaded are not loaded twice.
-- Difference from the initial COPY: a pipe cannot abort a statement; a bad file is SKIPPED and shows up in
-- COPY_HISTORY / SYSTEM$PIPE_STATUS, never half-loaded. Run as ROLE_ELT_ADMIN.
-- =============================================================================
USE ROLE ROLE_ELT_ADMIN;
USE WAREHOUSE WH_ELT;

CREATE OR REPLACE PIPE EDW_BRONZE.LANDING.PIPE_SAP_GL_ACTUALS_MONTHLY AUTO_INGEST = TRUE INTEGRATION = 'NINT_EDW_LANDING'
  AS COPY INTO EDW_BRONZE.RAW.SAP_GL_ACTUALS_MONTHLY FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sap_gl_actuals_monthly.csv
  FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'SKIP_FILE';
CREATE OR REPLACE PIPE EDW_BRONZE.LANDING.PIPE_SAP_CO_BUDGET_MONTHLY AUTO_INGEST = TRUE INTEGRATION = 'NINT_EDW_LANDING'
  AS COPY INTO EDW_BRONZE.RAW.SAP_CO_BUDGET_MONTHLY FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sap_co_budget_monthly.csv
