-- Is the listener healthy? (executionState RUNNING, pendingFileCount 0 when idle)
SELECT SYSTEM$PIPE_STATUS('EDW_BRONZE.LANDING.PIPE_PORTAL_SLA_EVENTS') AS pipe_status;
SHOW PIPES IN SCHEMA EDW_BRONZE.LANDING;
